// NODE 7: Extract theme from Groq response, fallback to keyword
// IMPORTANT: After HTTP Request node, $input.item.json is the Groq API response.
// Original review fields (rating, title, text, date) must be read from the
// paired item in the Keyword Pre-classify node using $('Keyword Pre-classify').item.json

const original = $('Keyword Pre-classify').item.json;

let themeNumber;
try {
  const groqText = $input.item.json.choices[0].message.content.trim();
  const parsed = parseInt(groqText.match(/[1-5]/)?.[0]);
  themeNumber = (parsed >= 1 && parsed <= 5) ? parsed : (original.keywordTheme || 2);
} catch (e) {
  themeNumber = original.keywordTheme || 2;
  console.log(`Groq parse error, using keyword fallback: ${themeNumber}`);
}

console.log(`Theme ${themeNumber} assigned to: "${(original.text || '').substring(0, 40)}..."`);

return {
  json: {
    rating: original.rating,
    title:  original.title,
    text:   original.text,
    date:   original.date,
    theme:  themeNumber
  }
};

// NODE 9: Aggregate themes + generate HTML pulse note

const THEMES = {
  1: { name: 'Onboarding & UX Confusion',   emoji: '🧭', blurb: 'Login flow playing hide-and-seek. Users need a GPS to navigate.' },
  2: { name: 'Performance & Technical Bugs', emoji: '🐛', blurb: 'Crashes and slowness are killing the vibe. Speed matters.' },
  3: { name: 'Missing Features & Requests',  emoji: '💡', blurb: 'Feature wishlist is growing. Time to peek at the suggestion box.' },
  4: { name: 'Trust & Security Concerns',    emoji: '🔒', blurb: 'KYC stuck in purgatory. Money anxiety spiking.' },
  5: { name: 'Support & Communication',      emoji: '📞', blurb: 'Support ghosting complaints. Response times need a Red Bull.' }
};

const ACTIONS = {
  1: (p) => `Simplify the login flow — ${p}% of users need a treasure map just to get in!`,
  2: (p) => `Speed boost urgently needed — ${p}% are watching loading spinners like it's dial-up TV.`,
  3: (p) => `Users are DMing their wishlist — ${p}% want more. Time to prioritise the top asks!`,
  4: (p) => `Verification hiccups are spooking ${p}% of users — smooth out those KYC speed bumps.`,
  5: (p) => `Support response times need a Red Bull — ${p}% of users are feeling ghosted.`
};

function parseDate(raw) {
  if (!raw) return null;
  const s = String(raw).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
    const d = new Date(s + 'T00:00:00Z');
    return isNaN(d.getTime()) ? null : d;
  }
  const mdy = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (mdy) {
    let [, m, d, y] = mdy;
    if (y.length === 2) y = '20' + y;
    const dt = new Date(`${y}-${m.padStart(2,'0')}-${d.padStart(2,'0')}T00:00:00Z`);
    return isNaN(dt.getTime()) ? null : dt;
  }
  if (/^\d+$/.test(s)) {
    const n = parseInt(s);
    const dt = n < 100000
      ? new Date(Date.UTC(1899, 11, 30) + n * 86400000)
      : new Date(n);
    return isNaN(dt.getTime()) ? null : dt;
  }
  const dt = new Date(s);
  return isNaN(dt.getTime()) ? null : dt;
}

function fmt(d) {
  return d ? d.toISOString().split('T')[0] : 'N/A';
}

const reviews = $input.all().map(i => i.json);
const total = reviews.length;
if (total === 0) throw new Error('No classified reviews received.');

// Count per theme
const counts = {};
reviews.forEach(r => {
  const t = r.theme || 2;
  if (!counts[t]) counts[t] = { count: 0, reviews: [] };
  counts[t].count++;
  counts[t].reviews.push(r);
});

// Ranked theme list
const themeList = Object.entries(counts).map(([id, data]) => ({
  id: parseInt(id),
  name: THEMES[id].name,
  emoji: THEMES[id].emoji,
  blurb: THEMES[id].blurb,
  count: data.count,
  percent: Math.round((data.count / total) * 100),
  reviews: data.reviews
})).sort((a, b) => b.count - a.count);

const top3 = themeList.slice(0, 3);

// 3 diverse quotes — one per top theme
// Priority: low-rated (1-3 stars) reviews with meaningful text, most recent first
// Fallback: any review with text if no low-rated ones exist
const quotes = [];
for (const theme of top3) {
  const allCandidates = theme.reviews
    .filter(r => r.text && r.text.trim().length > 20)
    .sort((a, b) => {
      const da = parseDate(a.date), db = parseDate(b.date);
      if (!da && !db) return 0;
      if (!da) return 1;
      if (!db) return -1;
      return db - da; // most recent first
    });

  // Prefer negative/neutral reviews (1-3 stars) — they carry actionable signal
  const negatives = allCandidates.filter(r => parseInt(r.rating) <= 3);
  const pick = negatives.length > 0 ? negatives[0] : allCandidates[0];

  if (pick) {
    const txt = pick.text.trim();
    quotes.push({
      text: txt.length > 120 ? txt.substring(0, 117) + '...' : txt,
      rating: parseInt(pick.rating) || 3,
      date: pick.date
    });
  } else {
    quotes.push(null);
  }
}

// 3 action nudges
const actions = top3.map(t => ACTIONS[t.id](t.percent));

// Date range
const parsedDates = reviews.map(r => parseDate(r.date)).filter(Boolean).sort((a, b) => a - b);
const startDate = fmt(parsedDates[0]);
const endDate   = fmt(parsedDates[parsedDates.length - 1]);
const weekLabel = fmt(new Date());

// Word count (plain text version for validation)
const plainText = [
  `Groww Review Pulse Week of ${weekLabel}`,
  `Reviews Analyzed ${total} Period ${startDate} to ${endDate}`,
  'Top 3 Themes This Week',
  ...top3.map(t => `${t.name} ${t.percent}% ${t.count} reviews ${t.blurb}`),
  'Real User Voices',
  ...quotes.map(q => q ? `${q.text} ${q.rating} star review ${q.date}` : ''),
  '3 Action Nudges',
  ...actions
].join(' ');
const wordCount = plainText.trim().split(/\s+/).length;
console.log(`Word count: ${wordCount}`);
if (wordCount > 250) console.warn(`Over 250 words (${wordCount}) — consider shortening blurbs`);

// ── HTML Email Body ────────────────────────────────────────────────
const starsHtml = (n) => '⭐'.repeat(Math.min(Math.max(n, 1), 5));

let html = `<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;padding:20px;color:#222;">`;

// Header
html += `
<div style="background:#00a36c;color:white;padding:20px 24px;border-radius:10px;margin-bottom:16px;">
  <h1 style="margin:0;font-size:20px;letter-spacing:0.5px;">📊 Groww Review Pulse</h1>
  <p style="margin:6px 0 0 0;opacity:0.9;font-size:14px;">Week of ${weekLabel}</p>
</div>`;

// Meta bar
html += `
<p style="background:#f4f7ff;padding:10px 16px;border-radius:6px;font-size:13px;margin-bottom:24px;">
  <strong>Reviews Analyzed:</strong> ${total} &nbsp;|&nbsp;
  <strong>Period:</strong> ${startDate} to ${endDate} &nbsp;|&nbsp;
  <strong>Source:</strong> Google Play Store
</p>`;

// Section header
html += `<h2 style="color:#00a36c;font-size:16px;border-bottom:2px solid #e0f2ec;padding-bottom:6px;margin-bottom:16px;">🎯 Top 3 Themes — with Quotes & Actions</h2>`;

// One card per theme: facts → humor → quote → action
top3.forEach((t, i) => {
  const q = quotes[i];
  const a = actions[i];

  html += `
<div style="border:1px solid #e0f2ec;border-radius:10px;padding:18px;margin-bottom:20px;">

  <!-- Theme facts (bold, prominent) -->
  <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;">
    <span style="font-size:22px;">${t.emoji}</span>
    <div>
      <strong style="font-size:15px;">#${i+1} ${t.name}</strong><br>
      <span style="background:#e0f2ec;color:#007a52;padding:2px 8px;border-radius:10px;font-size:12px;font-weight:bold;">
        ${t.percent}% of reviews &bull; ${t.count} out of ${total}
      </span>
    </div>
  </div>

  <!-- Humorous insight (italic, separate from facts) -->
  <p style="margin:8px 0 12px 0;font-style:italic;color:#666;font-size:13px;border-left:3px solid #b2dfdb;padding-left:10px;">
    ${t.blurb}
  </p>

  <!-- Real user quote -->
  ${q ? `
  <div style="background:#f9fffe;border-left:4px solid #00a36c;padding:10px 14px;border-radius:0 6px 6px 0;margin-bottom:12px;">
    <p style="margin:0 0 6px 0;font-size:14px;">&ldquo;${q.text}&rdquo;</p>
    <span style="font-size:12px;color:#888;">${starsHtml(q.rating)} ${q.rating}-star review &bull; ${q.date}</span>
  </div>` : ''}

  <!-- Action idea -->
  ${a ? `
  <div style="background:#fff8e1;border:1px solid #ffe082;border-radius:6px;padding:10px 14px;">
    <span style="font-size:12px;font-weight:bold;color:#f59e0b;">⚡ ACTION IDEA</span><br>
    <span style="font-size:14px;">${a}</span>
  </div>` : ''}

</div>`;
});

// Footer
html += `
<div style="text-align:center;margin-top:24px;padding:16px;background:#f4f7ff;border-radius:8px;">
  <p style="margin:0;font-style:italic;color:#555;font-size:15px;">Laugh. Learn. Iterate. 🚀</p>
</div>
<p style="text-align:center;font-size:11px;color:#bbb;margin-top:12px;">
  ${total} Play Store reviews &bull; ${wordCount} words &bull; Powered by n8n + Groq
</p>`;

html += `</div>`;

const top3Names = top3.map(t => `${t.emoji} ${t.name}`);

return [{
  json: {
    htmlBody:   html,
    wordCount:  wordCount,
    top3Themes: top3Names,
    reviewCount: total,
    dateRange:  `${startDate} to ${endDate}`,
    weekLabel:  weekLabel
  }
}];
